const adminUrl=window.location.href.replace("auth-frame/","")+"api/admin",siteOrigin="http://localhost:2368";window.addEventListener("message",async function(t){if(t.origin!==siteOrigin)return void console.warn("Ignored message to admin auth iframe because of mismatch in origin","expected",siteOrigin,"got",t.origin,"with data",t.data);let n=null;try{n=JSON.parse(t.data)}catch(t){console.error(t)}function a(a,i){t.source.postMessage(JSON.stringify({uid:n.uid,error:a,result:i}),siteOrigin)}if("browseComments"===n.action)try{const{postId:t,params:i}=n,e=await fetch(adminUrl+`/comments/post/${t}/?${new URLSearchParams(i).toString()}`);a(null,await e.json())}catch(t){a(t,null)}if("getReplies"===n.action)try{const{commentId:t,params:i}=n,e=await fetch(adminUrl+`/comments/${t}/replies/?${new URLSearchParams(i).toString()}`);a(null,await e.json())}catch(t){a(t,null)}if("readComment"===n.action)try{const{commentId:t,params:i}=n,e=await fetch(adminUrl+"/comments/"+t+"/?"+new URLSearchParams(i).toString());a(null,await e.json())}catch(t){a(t,null)}if("getUser"===n.action)try{const t=await fetch(adminUrl+"/users/me/?include=roles");a(null,await t.json())}catch(t){a(t,null)}if("hideComment"===n.action)try{const t=await fetch(adminUrl+"/comments/"+n.id+"/",{method:"PUT",body:JSON.stringify({comments:[{id:n.id,status:"hidden"}]}),headers:{"Content-Type":"application/json"}});a(null,await t.json())}catch(t){a(t,null)}if("showComment"===n.action)try{const t=await fetch(adminUrl+"/comments/"+n.id+"/",{method:"PUT",body:JSON.stringify({comments:[{id:n.id,status:"published"}]}),headers:{"Content-Type":"application/json"}});a(null,await t.json())}catch(t){a(t,null)}});